ALTER TABLE "professional_links" ADD CONSTRAINT "professional_links_verification_complete" CHECK (("professional_links"."verified_provider" is null and "professional_links"."verified_provider_user_id" is null and "professional_links"."verified_at" is null) or ("professional_links"."verified_provider" is not null and "professional_links"."verified_provider" in ('github', 'linkedin') and "professional_links"."verified_provider_user_id" is not null and btrim("professional_links"."verified_provider_user_id") <> '' and "professional_links"."verified_at" is not null));